def get_stock_price(api_key, symbol, market=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        # Similar style to existing ids, but unique enough locally.
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(24)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(tool, frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                vc = dr.get("vendor_call_count")
                if isinstance(vc, int) and vc > 0:
                    s += vc
        return s

    def _log_request_row(data_requests, row):
        data_requests.append(row)
        _save("data_requests.json", data_requests)

    def _update_key_last_used(api_keys, key_row):
        now = _utcnow()
        changed = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    def _resolve_active_key(api_key_param, api_keys):
        # Relax the too-strict ^avk_01H... pattern seen in broken code: accept any avk_... id.
        if not isinstance(api_key_param, str) or not api_key_param.strip():
            return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        if not api_key_param.startswith("avk_"):
            return None, _err("VALIDATION_ERROR", "api_key must start with 'avk_'")
        key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_param), None)
        if not key_row:
            return None, _err("UNAUTHORIZED", "Unknown api_key")
        return key_row, None

    # ---- Validate inputs ----
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be boolean when provided")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if market is not None and (not isinstance(market, str) or not market.strip()):
        return _err("VALIDATION_ERROR", "market must be a non-empty string when provided")

    sym = symbol.strip().upper()
    mkt = market.strip().upper() if isinstance(market, str) and market.strip() else None

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")
    response_snapshots = _load("response_snapshots.json")

    key_row, key_err = _resolve_active_key(api_key, api_keys)
    if key_err:
        return key_err

    now = _utcnow()
    now_iso = _iso(now)

    # Resolve asset: equity by (symbol, market?) with preference for active assets
    candidates = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("asset_type") != "equity":
            continue
        if str(a.get("symbol", "")).upper() != sym:
            continue
        if mkt is not None and str(a.get("market") or "").upper() != mkt:
            continue
        candidates.append(a)
    if not candidates:
        # Must still log a request row (tied to an active api key row).
        fp = _fingerprint({"tool": "get_stock_price", "symbol": sym, "market": mkt})
        req_id = _new_id("req")
        row = {
            "id": req_id,
            "api_key_id": key_row["id"],
            "tool_name": "get_stock_price",
            "asset_id": None,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "indicator": None,
            "interval": None,
            "time_period": None,
            "series_type": None,
            "outputsize": None,
            "vendor_function": "GLOBAL_QUOTE",
            "request_fingerprint": fp,
            "status": "failed",
            "http_status": 400,
            "error_code": "PARAM_VALIDATION",
            "error_message": "Symbol mapping failed for requested equity asset.",
            "vendor_call_count": 0,
            "response_snapshot_id": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        _log_request_row(data_requests, row)
        return _err("NOT_FOUND", "Equity asset not found for requested symbol/market", symbol=sym, market=mkt)

    def _asset_rank(a):
        st = a.get("status")
        upd = _parse_dt(a.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (0 if st == "active" else 1, -int(upd.timestamp()))

    candidates.sort(key=_asset_rank)
    asset = candidates[0]
    asset_id = asset.get("id")

    # Create data_requests row (queued) for every call, even reads.
    fp = _fingerprint({"tool": "get_stock_price", "asset_id": asset_id, "symbol": sym, "market": mkt})
    req_id = _new_id("req")
    vendor_function = "GLOBAL_QUOTE"
    req = {
        "id": req_id,
        "api_key_id": key_row["id"],
        "tool_name": "get_stock_price",
        "asset_id": asset_id,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": vendor_function,
        "request_fingerprint": fp,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_request_row(data_requests, req)

    # If key not active -> must end failed/rate_limited with vendor_call_count=0.
    if key_row.get("status") != "active":
        # queued -> rate_limited allowed
        if not _can_transition("data_requests", "queued", "rate_limited"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
        else:
            req["status"] = "rate_limited"
            req["http_status"] = 429
            req["error_code"] = "KEY_INACTIVE"
            req["error_message"] = f"API key is {key_row.get('status')}"
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    # Enforce request count quotas (daily/minute) against created data_requests including this one.
    day_start, day_end = _day_bounds_utc(now)
    minute_start = now - datetime.timedelta(minutes=1)

    daily_count = _count_requests(key_row["id"], day_start, day_end, data_requests)
    minute_count = _count_requests(key_row["id"], minute_start, now + datetime.timedelta(seconds=1), data_requests)

    qd = key_row.get("quota_daily_requests")
    qm = key_row.get("quota_minute_requests")
    qd = qd if isinstance(qd, int) and qd >= 0 else 0
    qm = qm if isinstance(qm, int) and qm >= 0 else 0

    if (qd and daily_count > qd) or (qm and minute_count > qm):
        if _can_transition("data_requests", "queued", "rate_limited"):
            req["status"] = "rate_limited"
            req["http_status"] = 429
            req["error_code"] = "QUOTA_DAILY_EXCEEDED" if (qd and daily_count > qd) else "QUOTA_MINUTE_EXCEEDED"
            req["error_message"] = "Daily request quota exceeded for this API key." if (qd and daily_count > qd) else "Minute request quota exceeded for this API key."
        else:
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("RATE_LIMIT", req["error_message"])

    # Cache lookup
    snap = None
    for s in response_snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("tool_name") != "get_stock_price":
            continue
        if s.get("request_fingerprint") != fp:
            continue
        if s.get("status") != "fresh":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        snap = s
        break

    if snap is not None and not force_refresh:
        # queued -> served_from_cache -> succeeded
        if not _can_transition("data_requests", "queued", "served_from_cache"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["updated_at"] = now_iso
            data_requests[-1] = req
            _save("data_requests.json", data_requests)
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition (queued -> served_from_cache)")
        req["status"] = "served_from_cache"
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)

        if not _can_transition("data_requests", "served_from_cache", "succeeded"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["updated_at"] = now_iso
            data_requests[-1] = req
            _save("data_requests.json", data_requests)
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition (served_from_cache -> succeeded)")

        req["status"] = "succeeded"
        req["http_status"] = 200
        req["vendor_call_count"] = 0
        req["response_snapshot_id"] = snap.get("id")
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        _update_key_last_used(api_keys, key_row)

        return {
            "data": {
                "asset": asset,
                "response_snapshot": snap,
                "vendor_raw_json": snap.get("vendor_raw_json"),
                "normalized_json": snap.get("normalized_json"),
                "served_from_cache": True,
            },
            "meta": {
                "data_request_id": req_id,
                "latency_ms": int((time.time() - t0) * 1000),
            },
        }

    # Need refresh: enforce daily vendor calls quota BEFORE calling vendor
    qv = key_row.get("quota_daily_vendor_calls")
    qv = qv if isinstance(qv, int) and qv >= 0 else 0
    used_vendor_calls = _sum_vendor_calls(key_row["id"], day_start, day_end, data_requests)
    if qv and (used_vendor_calls + 1 > qv):
        if _can_transition("data_requests", "queued", "rate_limited"):
            req["status"] = "rate_limited"
            req["http_status"] = 429
            req["error_code"] = "VENDOR_CALLS_DAILY_EXCEEDED"
            req["error_message"] = "Daily vendor call budget exceeded; request blocked before upstream fetch."
            req["vendor_call_count"] = 0
        else:
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("QUOTA_EXCEEDED", req["error_message"])

    # queued -> fetching
    if not _can_transition("data_requests", "queued", "fetching"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (queued -> fetching)")
    req["status"] = "fetching"
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)

    # Offline "vendor call": derive a plausible payload from existing snapshot if any, else minimal.
    # This still counts as a vendor call because cache was missing/stale/forced.
    base_payload = None
    if snap is None:
        # maybe stale/invalid snapshot exists; use latest for same fp regardless of status for continuity
        for s in response_snapshots:
            if isinstance(s, dict) and s.get("tool_name") == "get_stock_price" and s.get("request_fingerprint") == fp:
                base_payload = s.get("vendor_raw_json")
                break
    else:
        base_payload = snap.get("vendor_raw_json")

    vendor_raw = base_payload if isinstance(base_payload, dict) else {}
    # ensure minimally identifiable
    vendor_raw = dict(vendor_raw)
    vendor_raw.setdefault("symbol", sym)
    if mkt:
        vendor_raw.setdefault("market", mkt)
    vendor_raw["fetched_at"] = now_iso

    normalized = {
        "symbol": sym,
        "market": mkt,
        "as_of": now_iso,
    }
    # try to reuse a close/price if present anywhere
    price = None
    for k in ("price", "close", "latestPrice", "05. price"):
        v = vendor_raw.get(k)
        if isinstance(v, (int, float)):
            price = float(v)
            break
        if isinstance(v, str):
            try:
                price = float(v)
                break
            except Exception:
                pass
    if price is not None:
        normalized["price"] = price

    # Upsert response snapshot by (tool_name, request_fingerprint)
    ttl_seconds = 60
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)

    existing_idx = None
    for i, s in enumerate(response_snapshots):
        if not isinstance(s, dict):
            continue
        if s.get("tool_name") == "get_stock_price" and s.get("request_fingerprint") == fp:
            existing_idx = i
            break

    if existing_idx is None:
        rsp_id = _new_id("rsp")
        rsp = {
            "id": rsp_id,
            "request_fingerprint": fp,
            "tool_name": "get_stock_price",
            "asset_id": asset_id,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "vendor_function": vendor_function,
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        response_snapshots.append(rsp)
    else:
        rsp = response_snapshots[existing_idx]
        rsp_id = rsp.get("id")
        rsp["asset_id"] = asset_id
        rsp["vendor_function"] = vendor_function
        rsp["vendor_raw_json"] = vendor_raw
        rsp["normalized_json"] = normalized
        # stale -> fresh is allowed; invalid is terminal but we can still update row content while keeping invalid?
        # Enforce lifecycle: invalid cannot transition; keep invalid only if already invalid.
        if rsp.get("status") in ("fresh", "stale"):
            rsp["status"] = "fresh"
        rsp["fetched_at"] = now_iso
        rsp["expires_at"] = _iso(expires_at)
        rsp["updated_at"] = now_iso
        response_snapshots[existing_idx] = rsp

    _save("response_snapshots.json", response_snapshots)

    # fetching -> succeeded
    if not _can_transition("data_requests", "fetching", "succeeded"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (fetching -> succeeded)")

    req["status"] = "succeeded"
    req["http_status"] = 200
    req["vendor_call_count"] = 1
    req["response_snapshot_id"] = rsp_id
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)
    _update_key_last_used(api_keys, key_row)

    return {
        "data": {
            "asset": asset,
            "response_snapshot": rsp,
            "vendor_raw_json": rsp.get("vendor_raw_json"),
            "normalized_json": rsp.get("normalized_json"),
            "served_from_cache": False,
        },
        "meta": {
            "data_request_id": req_id,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def get_company_overview(api_key, symbol, market=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(24)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                vc = dr.get("vendor_call_count")
                if isinstance(vc, int) and vc > 0:
                    s += vc
        return s

    def _log_request_row(data_requests, row):
        data_requests.append(row)
        _save("data_requests.json", data_requests)

    def _update_key_last_used(api_keys, key_row):
        now = _utcnow()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                _save("api_keys.json", api_keys)
                break

    # Validate inputs (relaxed api_key format)
    if not isinstance(api_key, str) or not api_key.strip() or not api_key.startswith("avk_"):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string starting with 'avk_'")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if market is not None and (not isinstance(market, str) or not market.strip()):
        return _err("VALIDATION_ERROR", "market must be a non-empty string when provided")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be boolean when provided")

    sym = symbol.strip().upper()
    mkt = market.strip().upper() if isinstance(market, str) and market.strip() else None

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
