    # Offline vendor call stub: update snapshot
    vendor_raw = {"Symbol": sym, "Market": mkt, "fetched_at": now_iso}
    normalized = {"symbol": sym, "market": mkt, "as_of": now_iso}

    ttl_seconds = 3600
