def get_daily_time_series(api_key, symbol, market=None, outputsize=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(24)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
