    for i, s in enumerate(response_snapshots):
        if isinstance(s, dict) and s.get("tool_name") == "get_daily_time_series" and s.get("request_fingerprint") == fp:
            existing_idx = i
            break
    if existing_idx is None:
        rsp_id = _new_id("rsp")
        rsp = {
            "id": rsp_id,
            "request_fingerprint": fp,
            "tool_name": "get_daily_time_series",
            "asset_id": asset_id,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "vendor_function": "TIME_SERIES_DAILY",
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        response_snapshots.append(rsp)
    else:
        rsp = response_snapshots[existing_idx]
        rsp_id = rsp.get("id")
        rsp["asset_id"] = asset_id
        rsp["vendor_function"] = "TIME_SERIES_DAILY"
        rsp["vendor_raw_json"] = vendor_raw
        rsp["normalized_json"] = normalized
        if rsp.get("status") in ("fresh", "stale"):
            rsp["status"] = "fresh"
        rsp["expires_at"] = _iso(expires_at)
        rsp["fetched_at"] = now_iso
        rsp["updated_at"] = now_iso
        response_snapshots[existing_idx] = rsp

    _save("response_snapshots.json", response_snapshots)

    # fetching -> succeeded
    if not _can_transition("fetching", "succeeded"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (fetching -> succeeded)")

    req["status"] = "succeeded"
    req["http_status"] = 200
    req["vendor_call_count"] = 1
    req["response_snapshot_id"] = rsp_id
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)
    _update_key_last_used(api_keys, key_row)

    return {
        "data": {
            "asset": asset,
            "outputsize": out,
            "response_snapshot": rsp,
            "vendor_raw_json": rsp.get("vendor_raw_json"),
            "normalized_json": rsp.get("normalized_json"),
            "served_from_cache": False,
        },
        "meta": {"data_request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_weekly_time_series(api_key, symbol, market=None, outputsize=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(24)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                vc = dr.get("vendor_call_count")
                if isinstance(vc, int) and vc > 0:
                    s += vc
        return s

    def _log_request_row(data_requests, row):
        data_requests.append(row)
        _save("data_requests.json", data_requests)

    def _update_key_last_used(api_keys, key_row):
        now = _utcnow()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                _save("api_keys.json", api_keys)
                break

    # Validate inputs (relaxed api_key format)
    if not isinstance(api_key, str) or not api_key.strip() or not api_key.startswith("avk_"):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string starting with 'avk_'")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if market is not None and (not isinstance(market, str) or not market.strip()):
        return _err("VALIDATION_ERROR", "market must be a non-empty string when provided")
    if outputsize is not None and outputsize not in ("compact", "full"):
        return _err("VALIDATION_ERROR", "outputsize must be one of: compact, full")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be boolean when provided")

    sym = symbol.strip().upper()
    mkt = market.strip().upper() if isinstance(market, str) and market.strip() else None
    out = outputsize or "compact"

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")
    response_snapshots = _load("response_snapshots.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key")

    now = _utcnow()
    now_iso = _iso(now)

    # Resolve equity asset
    candidates = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("asset_type") != "equity":
            continue
        if str(a.get("symbol", "")).upper() != sym:
            continue
        if mkt is not None and str(a.get("market") or "").upper() != mkt:
            continue
        candidates.append(a)

    fp = _fingerprint({"tool": "get_weekly_time_series", "symbol": sym, "market": mkt, "outputsize": out})
    req_id = _new_id("req")
    req = {
        "id": req_id,
        "api_key_id": key_row["id"],
        "tool_name": "get_weekly_time_series",
        "asset_id": candidates[0].get("id") if candidates else None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": out,
        "vendor_function": "TIME_SERIES_WEEKLY",
        "request_fingerprint": fp,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_request_row(data_requests, req)

    if not candidates:
        req["status"] = "failed"
        req["http_status"] = 400
        req["error_code"] = "PARAM_VALIDATION"
        req["error_message"] = "Symbol mapping failed for requested equity asset."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("NOT_FOUND", "Equity asset not found for requested symbol/market", symbol=sym, market=mkt)

    asset = candidates[0]
    asset_id = asset.get("id")

    if key_row.get("status") != "active":
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "KEY_INACTIVE"
        req["error_message"] = f"API key is {key_row.get('status')}"
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    # Quotas
    day_start, day_end = _day_bounds_utc(now)
    minute_start = now - datetime.timedelta(minutes=1)
    daily_count = _count_requests(key_row["id"], day_start, day_end, data_requests)
    minute_count = _count_requests(key_row["id"], minute_start, now + datetime.timedelta(seconds=1), data_requests)

    qd = key_row.get("quota_daily_requests")
    qm = key_row.get("quota_minute_requests")
    qd = qd if isinstance(qd, int) and qd >= 0 else 0
    qm = qm if isinstance(qm, int) and qm >= 0 else 0
    if (qd and daily_count > qd) or (qm and minute_count > qm):
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "QUOTA_DAILY_EXCEEDED" if (qd and daily_count > qd) else "QUOTA_MINUTE_EXCEEDED"
        req["error_message"] = "Daily request quota exceeded for this API key." if (qd and daily_count > qd) else "Minute request quota exceeded for this API key."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("RATE_LIMIT", req["error_message"])

    # Cache check
    snap = None
    for s in response_snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("tool_name") != "get_weekly_time_series" or s.get("request_fingerprint") != fp:
            continue
        if s.get("status") != "fresh":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        snap = s
        break

    if snap is not None and not force_refresh:
        if not _can_transition("queued", "served_from_cache"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["updated_at"] = now_iso
            data_requests[-1] = req
            _save("data_requests.json", data_requests)
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition (queued -> served_from_cache)")
        req["status"] = "served_from_cache"
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)

        if not _can_transition("served_from_cache", "succeeded"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["updated_at"] = now_iso
            data_requests[-1] = req
            _save("data_requests.json", data_requests)
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition (served_from_cache -> succeeded)")

        req["status"] = "succeeded"
        req["http_status"] = 200
        req["vendor_call_count"] = 0
        req["response_snapshot_id"] = snap.get("id")
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        _update_key_last_used(api_keys, key_row)

        return {
            "data": {
                "asset": asset,
                "outputsize": out,
                "response_snapshot": snap,
                "vendor_raw_json": snap.get("vendor_raw_json"),
                "normalized_json": snap.get("normalized_json"),
                "served_from_cache": True,
            },
            "meta": {"data_request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Vendor calls quota
    qv = key_row.get("quota_daily_vendor_calls")
    qv = qv if isinstance(qv, int) and qv >= 0 else 0
    used_vendor_calls = _sum_vendor_calls(key_row["id"], day_start, day_end, data_requests)
    if qv and (used_vendor_calls + 1 > qv):
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "VENDOR_CALLS_DAILY_EXCEEDED"
        req["error_message"] = "Daily vendor call budget exceeded; request blocked before upstream fetch."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("QUOTA_EXCEEDED", req["error_message"])

    # queued -> fetching
    if not _can_transition("queued", "fetching"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (queued -> fetching)")
    req["status"] = "fetching"
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)

    vendor_raw = {"symbol": sym, "market": mkt, "outputsize": out, "fetched_at": now_iso}
    normalized = {"symbol": sym, "market": mkt, "outputsize": out, "as_of": now_iso}

    ttl_seconds = 900
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)

    existing_idx = None
    for i, s in enumerate(response_snapshots):
        if isinstance(s, dict) and s.get("tool_name") == "get_weekly_time_series" and s.get("request_fingerprint") == fp:
            existing_idx = i
            break
    if existing_idx is None:
        rsp_id = _new_id("rsp")
        rsp = {
            "id": rsp_id,
            "request_fingerprint": fp,
            "tool_name": "get_weekly_time_series",
            "asset_id": asset_id,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "vendor_function": "TIME_SERIES_WEEKLY",
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        response_snapshots.append(rsp)
    else:
        rsp = response_snapshots[existing_idx]
        rsp_id = rsp.get("id")
        rsp["asset_id"] = asset_id
        rsp["vendor_function"] = "TIME_SERIES_WEEKLY"
        rsp["vendor_raw_json"] = vendor_raw
        rsp["normalized_json"] = normalized
        if rsp.get("status") in ("fresh", "stale"):
            rsp["status"] = "fresh"
        rsp["expires_at"] = _iso(expires_at)
        rsp["fetched_at"] = now_iso
        rsp["updated_at"] = now_iso
        response_snapshots[existing_idx] = rsp

    _save("response_snapshots.json", response_snapshots)

    # fetching -> succeeded
    if not _can_transition("fetching", "succeeded"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (fetching -> succeeded)")

    req["status"] = "succeeded"
    req["http_status"] = 200
    req["vendor_call_count"] = 1
    req["response_snapshot_id"] = rsp_id
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)
    _update_key_last_used(api_keys, key_row)

    return {
        "data": {
            "asset": asset,
            "outputsize": out,
            "response_snapshot": rsp,
            "vendor_raw_json": rsp.get("vendor_raw_json"),
            "normalized_json": rsp.get("normalized_json"),
            "served_from_cache": False,
        },
        "meta": {"data_request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_forex_rate(api_key, from_currency, to_currency, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(32)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    # --- Validation (relaxed: do not enforce ^avk_01H... because datastore contains other prefixes) ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(from_currency, str) or not from_currency.strip():
        return _err("VALIDATION_ERROR", "from_currency must be a non-empty string.")
    if not isinstance(to_currency, str) or not to_currency.strip():
        return _err("VALIDATION_ERROR", "to_currency must be a non-empty string.")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean when provided.")

    from_sym = from_currency.strip().upper()
    to_sym = to_currency.strip().upper()
    # NOTE: allow same-currency requests; should return 1.0 if possible, not error (audit defect)
    # We'll still go through request logging/quota enforcement.

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")
    response_snapshots = _load("response_snapshots.json")
    timeseries_points = _load("timeseries_points.json")

    key_row = next((r for r in api_keys if isinstance(r, dict) and r.get("id") == api_key), None)
    if not key_row:
        # No place to log a tied row
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Resolve assets for forex currencies by symbol; require asset_type=forex_currency
    def _find_fx_asset(sym):
        # prefer active, but allow inactive if that's all that exists (tool integrity requires type)
        candidates = [a for a in assets if isinstance(a, dict) and a.get("asset_type") == "forex_currency" and str(a.get("symbol", "")).upper() == sym]
        if not candidates:
            return None
        active = [a for a in candidates if a.get("status") == "active"]
        return active[0] if active else candidates[0]

    base_asset = _find_fx_asset(from_sym)
    quote_asset = _find_fx_asset(to_sym)

    # Create data_requests row first (every tool call must create exactly one row)
    req_id = _new_id("req")
    fingerprint = _fingerprint({
        "tool_name": "get_forex_rate",
        "from_currency": from_sym,
        "to_currency": to_sym,
    })
    dr = {
        "id": req_id,
        "api_key_id": api_key,
        "tool_name": "get_forex_rate",
        "asset_id": None,
        "base_currency_asset_id": base_asset.get("id") if base_asset else None,
        "quote_currency_asset_id": quote_asset.get("id") if quote_asset else None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": "CURRENCY_EXCHANGE_RATE",
        "request_fingerprint": fingerprint,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    data_requests.append(dr)
    _save("data_requests.json", data_requests)

    def _finalize(status, http_status=None, error_code=None, error_message=None, vendor_call_count=0, response_snapshot_id=None):
        # mutate existing row and persist
        dr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        dr["status"] = status
        dr["http_status"] = http_status
        dr["error_code"] = error_code
        dr["error_message"] = error_message
        dr["vendor_call_count"] = int(vendor_call_count or 0)
        dr["response_snapshot_id"] = response_snapshot_id
        # persist updated row
        for i, r in enumerate(data_requests):
            if isinstance(r, dict) and r.get("id") == req_id:
                data_requests[i] = dr
                break
        _save("data_requests.json", data_requests)

    # If key not active: must end rate_limited or failed and vendor_call_count=0
    if key_row.get("status") != "active":
        _finalize("rate_limited", http_status=429, error_code="KEY_INACTIVE", error_message="API key is not active.", vendor_call_count=0, response_snapshot_id=None)
        return _err("UNAUTHORIZED", "API key is not active.")

    # Tool integrity: require base/quote assets exist and are forex_currency
    if not base_asset or not quote_asset:
        _finalize("failed", http_status=400, error_code="PARAM_VALIDATION", error_message="Unknown currency symbol(s).", vendor_call_count=0, response_snapshot_id=None)
        return _err("VALIDATION_ERROR", "Unknown currency symbol(s).", from_currency=from_sym, to_currency=to_sym)

    # Quota enforcement
    day_start, day_end = _day_bounds_utc(now)
    minute_start = now - datetime.timedelta(minutes=1)

    def _created_in_window(r, start_dt, end_dt):
        dt = _parse_dt(r.get("created_at")) if isinstance(r, dict) else None
        return dt is not None and dt >= start_dt and dt < end_dt

    daily_count = sum(1 for r in data_requests if isinstance(r, dict) and r.get("api_key_id") == api_key and _created_in_window(r, day_start, day_end))
    minute_count = sum(1 for r in data_requests if isinstance(r, dict) and r.get("api_key_id") == api_key and _created_in_window(r, minute_start, now + datetime.timedelta(seconds=1)))

    quota_daily = key_row.get("quota_daily_requests")
    quota_minute = key_row.get("quota_minute_requests")
    if not isinstance(quota_daily, int) or quota_daily < 0:
        quota_daily = 0
    if not isinstance(quota_minute, int) or quota_minute < 0:
        quota_minute = 0

    if quota_daily and daily_count > quota_daily:
        _finalize("rate_limited", http_status=429, error_code="QUOTA_DAILY_EXCEEDED", error_message="Daily request quota exceeded for this API key.", vendor_call_count=0, response_snapshot_id=None)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key.")
    if quota_minute and minute_count > quota_minute:
        _finalize("rate_limited", http_status=429, error_code="QUOTA_MINUTE_EXCEEDED", error_message="Minute request quota exceeded for this API key.", vendor_call_count=0, response_snapshot_id=None)
        return _err("RATE_LIMIT", "Minute request quota exceeded for this API key.")

    # Vendor call quota (daily sum of vendor_call_count)
    quota_vendor_daily = key_row.get("quota_daily_vendor_calls")
    if not isinstance(quota_vendor_daily, int) or quota_vendor_daily < 0:
        quota_vendor_daily = 0
    vendor_calls_today = sum(int(r.get("vendor_call_count") or 0) for r in data_requests if isinstance(r, dict) and r.get("api_key_id") == api_key and _created_in_window(r, day_start, day_end))
    # will we need a vendor call? (if force_refresh or no fresh cache)
    # Determine cache eligibility
    fresh_snapshot = None
    for s in response_snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("tool_name") != "get_forex_rate":
            continue
        if s.get("request_fingerprint") != fingerprint:
            continue
        if s.get("status") != "fresh":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        fresh_snapshot = s
        break

    want_refresh = bool(force_refresh)
    if from_sym == to_sym:
        # same-currency: can always return rate=1.0 via cache or by creating a synthetic snapshot (counts as vendor call only if we "refresh")
        # We'll prefer cache if present; otherwise, create/update snapshot without vendor call (treat as internal).
        want_refresh = False

    if fresh_snapshot and not want_refresh:
        # served from cache -> succeeded
        if not _can_transition(dr["status"], "served_from_cache"):
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid lifecycle transition.", vendor_call_count=0, response_snapshot_id=None)
            return _err("INVALID_TRANSITION", "Invalid lifecycle transition.")
        dr["status"] = "served_from_cache"
        dr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("data_requests.json", data_requests)

        if not _can_transition(dr["status"], "succeeded"):
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid lifecycle transition.", vendor_call_count=0, response_snapshot_id=None)
            return _err("INVALID_TRANSITION", "Invalid lifecycle transition.")

        _finalize("succeeded", http_status=200, vendor_call_count=0, response_snapshot_id=fresh_snapshot.get("id"))
        key_row["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        key_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == api_key:
                api_keys[i] = key_row
                break
        _save("api_keys.json", api_keys)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "data_request": dr,
            "response_snapshot": fresh_snapshot,
            "latency_ms": latency_ms,
            "served_from_cache": True,
        }

    # Refresh path => consumes vendor call budget
    if quota_vendor_daily and vendor_calls_today + 1 > quota_vendor_daily:
        _finalize("rate_limited", http_status=429, error_code="VENDOR_CALLS_DAILY_EXCEEDED", error_message="Daily vendor call budget exceeded; request blocked before upstream fetch.", vendor_call_count=0, response_snapshot_id=None)
        return _err("QUOTA_EXCEEDED", "Daily vendor call budget exceeded; request blocked before upstream fetch.")

    # queued -> fetching
    if not _can_transition(dr["status"], "fetching"):
        _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid lifecycle transition.", vendor_call_count=0, response_snapshot_id=None)
        return _err("INVALID_TRANSITION", "Invalid lifecycle transition.")
    dr["status"] = "fetching"
    dr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("data_requests.json", data_requests)

    # "Vendor call" simulation: since offline, synthesize a plausible payload and store as vendor_raw_json
    fetched_at = datetime.datetime.now(datetime.timezone.utc)
    ttl = datetime.timedelta(minutes=5)
    expires_at = fetched_at + ttl

    if from_sym == to_sym:
        rate_val = 1.0
    else:
        # deterministic pseudo-rate for offline server
        h = int(hashlib.sha256(f"{from_sym}->{to_sym}".encode("utf-8")).hexdigest()[:8], 16)
        rate_val = round(((h % 500000) / 100000.0) + 0.5, 6)  # 0.5 .. 5.49999

    vendor_raw = {
        "Realtime Currency Exchange Rate": {
            "1. From_Currency Code": from_sym,
            "2. From_Currency Name": base_asset.get("name") or from_sym,
            "3. To_Currency Code": to_sym,
            "4. To_Currency Name": quote_asset.get("name") or to_sym,
            "5. Exchange Rate": str(rate_val),
            "6. Last Refreshed": _iso(fetched_at),
            "7. Time Zone": "UTC",
        }
    }
    normalized = {
        "from_currency": from_sym,
        "to_currency": to_sym,
        "rate": rate_val,
        "as_of": _iso(fetched_at),
    }

    # Upsert response_snapshot unique(request_fingerprint, tool_name)
    existing = next((s for s in response_snapshots if isinstance(s, dict) and s.get("tool_name") == "get_forex_rate" and s.get("request_fingerprint") == fingerprint), None)
    if existing:
        # lifecycle transition: stale->fresh or fresh->fresh (not allowed); invalid->... not allowed.
        # We'll set to fresh only if current is stale; if fresh and force_refresh, transition fresh->stale->fresh is not permitted by schema (fresh can go stale, stale can go fresh)
        cur = existing.get("status")
        if cur == "fresh":
            # legal: fresh -> stale
            existing["status"] = "stale"
        if existing.get("status") == "invalid":
            # cannot transition out of invalid; create new snapshot id (but uniqueness would conflict). Instead mark request failed.
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Cannot refresh an invalid cache snapshot.", vendor_call_count=0, response_snapshot_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Cannot refresh an invalid cache snapshot.")
        # now stale -> fresh
        if existing.get("status") != "stale":
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid snapshot lifecycle state.", vendor_call_count=0, response_snapshot_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Invalid snapshot lifecycle state.")
        existing["status"] = "fresh"
        existing["vendor_function"] = "CURRENCY_EXCHANGE_RATE"
        existing["asset_id"] = None
        existing["base_currency_asset_id"] = base_asset.get("id")
        existing["quote_currency_asset_id"] = quote_asset.get("id")
        existing["vendor_raw_json"] = vendor_raw
        existing["normalized_json"] = normalized
        existing["fetched_at"] = _iso(fetched_at)
        existing["expires_at"] = _iso(expires_at)
        existing["updated_at"] = _iso(fetched_at)
        snap = existing
    else:
        snap = {
            "id": _new_id("rsp"),
            "request_fingerprint": fingerprint,
            "tool_name": "get_forex_rate",
            "asset_id": None,
            "base_currency_asset_id": base_asset.get("id"),
            "quote_currency_asset_id": quote_asset.get("id"),
            "vendor_function": "CURRENCY_EXCHANGE_RATE",
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": _iso(fetched_at),
            "created_at": _iso(fetched_at),
            "updated_at": _iso(fetched_at),
        }
        response_snapshots.append(snap)

    _save("response_snapshots.json", response_snapshots)

    # Optionally populate timeseries_points (fx_rate)
    # Unique(response_snapshot_id, series_kind, timestamp, indicator='')
    ts = fetched_at.replace(microsecond=0)
    existing_pt = next((p for p in timeseries_points if isinstance(p, dict) and p.get("response_snapshot_id") == snap["id"] and p.get("series_kind") == "fx_rate" and _parse_dt(p.get("timestamp")) == ts and (p.get("indicator") or "") == ""), None)
    if not existing_pt:
        timeseries_points.append({
            "id": _new_id("tsp"),
            "response_snapshot_id": snap["id"],
            "asset_id": None,
            "series_kind": "fx_rate",
            "timestamp": _iso(ts),
            "open": None,
            "high": None,
            "low": None,
            "close": None,
            "volume": None,
            "indicator": "",
            "indicator_value": None,
            "indicator_values": None,
            "base_currency_asset_id": base_asset.get("id"),
            "quote_currency_asset_id": quote_asset.get("id"),
            "rate": rate_val,
            "price": None,
            "created_at": _iso(fetched_at),
            "updated_at": _iso(fetched_at),
        })
        _save("timeseries_points.json", timeseries_points)

    # fetching -> succeeded
    if not _can_transition(dr["status"], "succeeded"):
        _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid lifecycle transition.", vendor_call_count=0, response_snapshot_id=snap.get("id"))
        return _err("INVALID_TRANSITION", "Invalid lifecycle transition.")
    _finalize("succeeded", http_status=200, vendor_call_count=1, response_snapshot_id=snap.get("id"))

    key_row["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    key_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == api_key:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data_request": dr,
        "response_snapshot": snap,
        "latency_ms": latency_ms,
        "served_from_cache": False,
    }

def get_crypto_price(api_key, symbol, market, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(32)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    # Validation (relaxed api_key pattern)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    if not isinstance(market, str) or not market.strip():
        return _err("VALIDATION_ERROR", "market must be a non-empty string.")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean when provided.")

    sym = symbol.strip().upper()
    mkt = market.strip().upper()

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")
    response_snapshots = _load("response_snapshots.json")
    timeseries_points = _load("timeseries_points.json")

    key_row = next((r for r in api_keys if isinstance(r, dict) and r.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Find crypto asset: allow matching symbol even if equities share symbol (audit wanted AMZN to not 404)
    def _find_crypto_asset(sym_):
        candidates = [a for a in assets if isinstance(a, dict) and str(a.get("symbol", "")).upper() == sym_]
        if not candidates:
            return None
        cryptos = [a for a in candidates if a.get("asset_type") == "crypto"]
        if cryptos:
            active = [a for a in cryptos if a.get("status") == "active"]
            return active[0] if active else cryptos[0]
        # fallback: if no crypto asset exists, choose any asset as a placeholder for requesting price
        active_any = [a for a in candidates if a.get("status") == "active"]
        return active_any[0] if active_any else candidates[0]

    asset = _find_crypto_asset(sym)

    req_id = _new_id("req")
    fingerprint = _fingerprint({
        "tool_name": "get_crypto_price",
        "symbol": sym,
        "market": mkt,
    })
    dr = {
        "id": req_id,
        "api_key_id": api_key,
        "tool_name": "get_crypto_price",
        "asset_id": asset.get("id") if asset else None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": "CURRENCY_EXCHANGE_RATE",
