    if not isinstance(quota_vendor_daily, int) or quota_vendor_daily < 0:
        quota_vendor_daily = 0
    vendor_calls_today = sum(int(r.get("vendor_call_count") or 0) for r in data_requests if isinstance(r, dict) and r.get("api_key_id") == api_key and _created_in_window(r, day_start, day_end))

    # Cache check
    fresh_snapshot = None
    for s in response_snapshots:
