    # Offline "vendor call": deterministic pseudo price
    fetched_at = datetime.datetime.now(datetime.timezone.utc)
    ttl = datetime.timedelta(minutes=5)
    expires_at = fetched_at + ttl
    h = int(hashlib.sha256(f"{sym}:{mkt}".encode("utf-8")).hexdigest()[:10], 16)
    price_val = round(((h % 200000000) / 100.0) + 0.01, 2)

    vendor_raw = {
        "Crypto": sym,
        "Market": mkt,
        "Price": str(price_val),
        "Last Refreshed": _iso(fetched_at),
        "Time Zone": "UTC",
    }
    normalized = {"symbol": sym, "market": mkt, "price": price_val, "as_of": _iso(fetched_at)}

    existing = next((s for s in response_snapshots if isinstance(s, dict) and s.get("tool_name") == "get_crypto_price" and s.get("request_fingerprint") == fingerprint), None)
    if existing:
        cur = existing.get("status")
        if cur == "fresh":
            existing["status"] = "stale"
        if existing.get("status") == "invalid":
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Cannot refresh an invalid cache snapshot.", vendor_call_count=0, response_snapshot_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Cannot refresh an invalid cache snapshot.")
        if existing.get("status") != "stale":
            _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid snapshot lifecycle state.", vendor_call_count=0, response_snapshot_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Invalid snapshot lifecycle state.")
        existing["status"] = "fresh"
        existing["vendor_function"] = "CRYPTO_PRICE"
        existing["asset_id"] = asset.get("id")
        existing["base_currency_asset_id"] = None
        existing["quote_currency_asset_id"] = None
        existing["vendor_raw_json"] = vendor_raw
        existing["normalized_json"] = normalized
        existing["fetched_at"] = _iso(fetched_at)
        existing["expires_at"] = _iso(expires_at)
        existing["updated_at"] = _iso(fetched_at)
        snap = existing
    else:
        snap = {
            "id": _new_id("rsp"),
            "request_fingerprint": fingerprint,
            "tool_name": "get_crypto_price",
            "asset_id": asset.get("id"),
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "vendor_function": "CRYPTO_PRICE",
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": _iso(fetched_at),
            "created_at": _iso(fetched_at),
            "updated_at": _iso(fetched_at),
        }
        response_snapshots.append(snap)
    _save("response_snapshots.json", response_snapshots)

    # timeseries point
    ts = fetched_at.replace(microsecond=0)
    existing_pt = next((p for p in timeseries_points if isinstance(p, dict) and p.get("response_snapshot_id") == snap["id"] and p.get("series_kind") == "crypto_price" and _parse_dt(p.get("timestamp")) == ts and (p.get("indicator") or "") == ""), None)
    if not existing_pt:
        timeseries_points.append({
            "id": _new_id("tsp"),
            "response_snapshot_id": snap["id"],
            "asset_id": asset.get("id"),
            "series_kind": "crypto_price",
            "timestamp": _iso(ts),
            "open": None,
            "high": None,
            "low": None,
            "close": None,
            "volume": None,
            "indicator": "",
            "indicator_value": None,
            "indicator_values": None,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "rate": None,
            "price": price_val,
            "created_at": _iso(fetched_at),
            "updated_at": _iso(fetched_at),
        })
        _save("timeseries_points.json", timeseries_points)

    # fetching -> succeeded
    if not _can_transition(dr["status"], "succeeded"):
        _finalize("failed", http_status=500, error_code="INVALID_TRANSITION", error_message="Invalid lifecycle transition.", vendor_call_count=0, response_snapshot_id=snap.get("id"))
        return _err("INVALID_TRANSITION", "Invalid lifecycle transition.")
    _finalize("succeeded", http_status=200, vendor_call_count=1, response_snapshot_id=snap.get("id"))

    key_row["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    key_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == api_key:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    return {
        "data_request": dr,
        "response_snapshot": snap,
        "latency_ms": int((time.time() - t0) * 1000),
        "served_from_cache": False,
    }

def get_technical_indicator(api_key, symbol, market=None, indicator=None, interval=None, time_period=None, series_type=None, outputsize=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(24)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    def _fingerprint(payload):
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _can_transition(frm, to):
        lifecycle = {
            "queued": ["fetching", "rate_limited", "failed"],
            "fetching": ["succeeded", "failed"],
            "served_from_cache": ["succeeded"],
            "succeeded": [],
            "failed": [],
            "rate_limited": [],
        }
        return to in lifecycle.get(frm, [])

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                vc = dr.get("vendor_call_count")
                if isinstance(vc, int) and vc > 0:
                    s += vc
        return s

    def _log_request_row(data_requests, row):
        data_requests.append(row)
        _save("data_requests.json", data_requests)

    def _update_key_last_used(api_keys, key_row):
        now = _utcnow()
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                _save("api_keys.json", api_keys)
                break

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip() or not api_key.startswith("avk_"):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string starting with 'avk_'")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    if market is not None and (not isinstance(market, str) or not market.strip()):
        return _err("VALIDATION_ERROR", "market must be a non-empty string when provided")
    if not isinstance(indicator, str) or not indicator.strip():
        return _err("VALIDATION_ERROR", "indicator is required")
    if not isinstance(interval, str) or not interval.strip():
        return _err("VALIDATION_ERROR", "interval is required")
    if not isinstance(series_type, str) or not series_type.strip():
        return _err("VALIDATION_ERROR", "series_type is required")
    if not isinstance(time_period, int) or time_period < 1 or time_period > 10000:
        return _err("VALIDATION_ERROR", "time_period must be an integer between 1 and 10000")
    if series_type.strip().lower() not in ("open", "high", "low", "close"):
        return _err("VALIDATION_ERROR", "series_type must be one of: open, high, low, close")
    if outputsize is not None and outputsize not in ("compact", "full"):
        return _err("VALIDATION_ERROR", "outputsize must be one of: compact, full")
    if force_refresh is not None and not isinstance(force_refresh, bool):
        return _err("VALIDATION_ERROR", "force_refresh must be boolean when provided")

    sym = symbol.strip().upper()
    mkt = market.strip().upper() if isinstance(market, str) and market.strip() else None
    ind = indicator.strip().upper()
    interv = interval.strip().lower()
    st = series_type.strip().lower()
    out = outputsize or "compact"

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")
    response_snapshots = _load("response_snapshots.json")
    timeseries_points = _load("timeseries_points.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key")

    now = _utcnow()
    now_iso = _iso(now)

    # Resolve equity asset for indicator
    candidates = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("asset_type") != "equity":
            continue
        if str(a.get("symbol", "")).upper() != sym:
            continue
        if mkt is not None and str(a.get("market") or "").upper() != mkt:
            continue
        candidates.append(a)

    fp = _fingerprint({
        "tool": "get_technical_indicator",
        "symbol": sym,
        "market": mkt,
        "indicator": ind,
        "interval": interv,
        "time_period": time_period,
        "series_type": st,
        "outputsize": out,
    })
    req_id = _new_id("req")
    req = {
        "id": req_id,
        "api_key_id": key_row["id"],
        "tool_name": "get_technical_indicator",
        "asset_id": candidates[0].get("id") if candidates else None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": ind,
        "interval": interv,
        "time_period": time_period,
        "series_type": st,
        "outputsize": out,
        "vendor_function": ind,
        "request_fingerprint": fp,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_request_row(data_requests, req)

    if not candidates:
        req["status"] = "failed"
        req["http_status"] = 400
        req["error_code"] = "PARAM_VALIDATION"
        req["error_message"] = "Symbol mapping failed for requested equity asset."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("NOT_FOUND", "Equity asset not found for requested symbol/market", symbol=sym, market=mkt)

    asset = candidates[0]
    asset_id = asset.get("id")

    if key_row.get("status") != "active":
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "KEY_INACTIVE"
        req["error_message"] = f"API key is {key_row.get('status')}"
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    # Quotas
    day_start, day_end = _day_bounds_utc(now)
    minute_start = now - datetime.timedelta(minutes=1)
    daily_count = _count_requests(key_row["id"], day_start, day_end, data_requests)
    minute_count = _count_requests(key_row["id"], minute_start, now + datetime.timedelta(seconds=1), data_requests)

    qd = key_row.get("quota_daily_requests")
    qm = key_row.get("quota_minute_requests")
    qd = qd if isinstance(qd, int) and qd >= 0 else 0
    qm = qm if isinstance(qm, int) and qm >= 0 else 0
    if (qd and daily_count > qd) or (qm and minute_count > qm):
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "QUOTA_DAILY_EXCEEDED" if (qd and daily_count > qd) else "QUOTA_MINUTE_EXCEEDED"
        req["error_message"] = "Daily request quota exceeded for this API key." if (qd and daily_count > qd) else "Minute request quota exceeded for this API key."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("RATE_LIMIT", req["error_message"])

    # Cache
    snap = None
    for s in response_snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("tool_name") != "get_technical_indicator" or s.get("request_fingerprint") != fp:
            continue
        if s.get("status") != "fresh":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        snap = s
        break

    if snap is not None and not force_refresh:
        req["status"] = "served_from_cache" if _can_transition("queued", "served_from_cache") else "failed"
        req["http_status"] = 200 if req["status"] == "served_from_cache" else 500
        req["vendor_call_count"] = 0
        req["response_snapshot_id"] = snap.get("id")
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)

        if req["status"] != "served_from_cache" or not _can_transition("served_from_cache", "succeeded"):
            req["status"] = "failed"
            req["http_status"] = 500
            req["error_code"] = "INVALID_TRANSITION"
            req["error_message"] = "Illegal lifecycle transition."
            req["updated_at"] = now_iso
            data_requests[-1] = req
            _save("data_requests.json", data_requests)
            return _err("INVALID_TRANSITION", "Illegal lifecycle transition for cached response")

        req["status"] = "succeeded"
        req["http_status"] = 200
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        _update_key_last_used(api_keys, key_row)

        return {
            "data": {
                "asset": asset,
                "indicator": ind,
                "interval": interv,
                "time_period": time_period,
                "series_type": st,
                "outputsize": out,
                "response_snapshot": snap,
                "vendor_raw_json": snap.get("vendor_raw_json"),
                "normalized_json": snap.get("normalized_json"),
                "served_from_cache": True,
            },
            "meta": {"data_request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Vendor calls quota
    qv = key_row.get("quota_daily_vendor_calls")
    qv = qv if isinstance(qv, int) and qv >= 0 else 0
    used_vendor_calls = _sum_vendor_calls(key_row["id"], day_start, day_end, data_requests)
    if qv and (used_vendor_calls + 1 > qv):
        req["status"] = "rate_limited" if _can_transition("queued", "rate_limited") else "failed"
        req["http_status"] = 429 if req["status"] == "rate_limited" else 500
        req["error_code"] = "VENDOR_CALLS_DAILY_EXCEEDED"
        req["error_message"] = "Daily vendor call budget exceeded; request blocked before upstream fetch."
        req["vendor_call_count"] = 0
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("QUOTA_EXCEEDED", req["error_message"])

    # queued -> fetching
    if not _can_transition("queued", "fetching"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (queued -> fetching)")
    req["status"] = "fetching"
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)

    # Offline vendor call stub
    vendor_raw = {
        "symbol": sym,
        "market": mkt,
        "indicator": ind,
        "interval": interv,
        "time_period": time_period,
        "series_type": st,
        "outputsize": out,
        "fetched_at": now_iso,
    }
    normalized = dict(vendor_raw)

    ttl_seconds = 60 if interv.endswith("min") else 300
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)

    existing_idx = None
    for i, s in enumerate(response_snapshots):
        if isinstance(s, dict) and s.get("tool_name") == "get_technical_indicator" and s.get("request_fingerprint") == fp:
            existing_idx = i
            break
    if existing_idx is None:
        rsp_id = _new_id("rsp")
        rsp = {
            "id": rsp_id,
            "request_fingerprint": fp,
            "tool_name": "get_technical_indicator",
            "asset_id": asset_id,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "vendor_function": ind,
            "vendor_raw_json": vendor_raw,
            "normalized_json": normalized,
            "status": "fresh",
            "expires_at": _iso(expires_at),
            "fetched_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        response_snapshots.append(rsp)
    else:
        rsp = response_snapshots[existing_idx]
        rsp_id = rsp.get("id")
        rsp["asset_id"] = asset_id
        rsp["vendor_function"] = ind
        rsp["vendor_raw_json"] = vendor_raw
        rsp["normalized_json"] = normalized
        if rsp.get("status") in ("fresh", "stale"):
            rsp["status"] = "fresh"
        rsp["expires_at"] = _iso(expires_at)
        rsp["fetched_at"] = now_iso
        rsp["updated_at"] = now_iso
        response_snapshots[existing_idx] = rsp
    _save("response_snapshots.json", response_snapshots)

    # Optionally upsert a single technical_indicator point
    ts_key = now.replace(microsecond=0)
    exists_point = False
    for p in timeseries_points:
        if not isinstance(p, dict):
            continue
        if p.get("response_snapshot_id") != rsp_id:
            continue
        if p.get("series_kind") != "technical_indicator":
            continue
        if (p.get("indicator") or "").upper() != ind:
            continue
        if _parse_dt(p.get("timestamp")) == ts_key:
            exists_point = True
            break
    if not exists_point:
        point = {
            "id": _new_id("tsp"),
            "response_snapshot_id": rsp_id,
            "asset_id": asset_id,
            "series_kind": "technical_indicator",
            "timestamp": _iso(ts_key),
            "open": None,
            "high": None,
            "low": None,
            "close": None,
            "volume": None,
            "indicator": ind,
            "indicator_value": None,
            "indicator_values": None,
            "base_currency_asset_id": None,
            "quote_currency_asset_id": None,
            "rate": None,
            "price": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        timeseries_points.append(point)
        _save("timeseries_points.json", timeseries_points)

    # fetching -> succeeded
    if not _can_transition("fetching", "succeeded"):
        req["status"] = "failed"
        req["http_status"] = 500
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal lifecycle transition."
        req["updated_at"] = now_iso
        data_requests[-1] = req
        _save("data_requests.json", data_requests)
        return _err("INVALID_TRANSITION", "Illegal lifecycle transition (fetching -> succeeded)")

    req["status"] = "succeeded"
    req["http_status"] = 200
    req["vendor_call_count"] = 1
    req["response_snapshot_id"] = rsp_id
    req["updated_at"] = now_iso
    data_requests[-1] = req
    _save("data_requests.json", data_requests)
    _update_key_last_used(api_keys, key_row)

    return {
        "data": {
            "asset": asset,
            "indicator": ind,
            "interval": interv,
            "time_period": time_period,
            "series_type": st,
            "outputsize": out,
            "response_snapshot": rsp,
            "vendor_raw_json": rsp.get("vendor_raw_json"),
            "normalized_json": rsp.get("normalized_json"),
            "served_from_cache": False,
        },
        "meta": {"data_request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_api_key_identity(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        st = s.strip()
        if not st:
            return None
        try:
            return datetime.datetime.fromisoformat(st.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_bounds_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        start = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return start, start + datetime.timedelta(days=1)

    def _count_requests(api_key_id, start_dt, end_dt, data_requests):
        c = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                c += 1
        return c

    def _sum_vendor_calls(api_key_id, start_dt, end_dt, data_requests):
        s = 0
        for dr in data_requests:
            if not isinstance(dr, dict):
                continue
            if dr.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(dr.get("created_at"))
            if created is None:
                continue
            if created >= start_dt and created < end_dt:
                vc = dr.get("vendor_call_count")
                if isinstance(vc, int) and vc > 0:
                    s += vc
        return s

    # Validate (relax pattern)
    if not isinstance(api_key, str) or not api_key.strip() or not api_key.startswith("avk_"):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string starting with 'avk_'")

    api_keys = _load("api_keys.json")
    data_requests = _load("data_requests.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key")
    if key_row.get("status") in ("revoked", "suspended"):
        return _err("UNAUTHORIZED", f"API key is {key_row.get('status')}")

    now = _utcnow()
    day_start, day_end = _day_bounds_utc(now)
    minute_start = now - datetime.timedelta(minutes=1)

    daily_requests = _count_requests(api_key, day_start, day_end, data_requests)
    minute_requests = _count_requests(api_key, minute_start, now + datetime.timedelta(seconds=1), data_requests)
    daily_vendor_calls = _sum_vendor_calls(api_key, day_start, day_end, data_requests)

    return {
        "data": {
            "id": key_row.get("id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "plan": key_row.get("plan"),
            "quota_daily_requests": key_row.get("quota_daily_requests"),
            "quota_minute_requests": key_row.get("quota_minute_requests"),
            "quota_daily_vendor_calls": key_row.get("quota_daily_vendor_calls"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
            "consumption": {
                "minute_requests": minute_requests,
                "daily_requests": daily_requests,
                "daily_vendor_calls": daily_vendor_calls,
            },
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def list_assets(api_key, asset_type=None, symbol=None, market=None, status=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        return f"{prefix}_{ms:x}".lower()

    def _fingerprint(payload):
        import hashlib
        norm = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    # Validate
    if not isinstance(api_key, str) or not api_key.strip() or not api_key.startswith("avk_"):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string starting with 'avk_'")
    if asset_type is not None and asset_type not in ("equity", "forex_currency", "crypto"):
        return _err("VALIDATION_ERROR", "asset_type must be one of: equity, forex_currency, crypto")
    if status is not None and status not in ("active", "inactive"):
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive")
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided")
    if market is not None and (not isinstance(market, str) or not market.strip()):
        return _err("VALIDATION_ERROR", "market must be a non-empty string when provided")
    if page is not None and (not isinstance(page, int) or page < 1):
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 200):
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    page = 1 if page is None else page
    page_size = 50 if page_size is None else page_size

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    now = _utcnow()
    now_iso = _iso(now)

    # Log this call as a data_requests row (read still counts for quotas)
    fp = _fingerprint({"tool": "list_assets", "filters": {"asset_type": asset_type, "symbol": symbol, "market": market, "status": status, "page": page, "page_size": page_size}})
    dr = {
        "id": _new_id("req"),
        "api_key_id": key_row["id"],
        "tool_name": "get_company_overview",  # closest enum tool; schema does not include list_assets. Use a real enum value.
        "asset_id": None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": None,
        "request_fingerprint": fp,
        "status": "served_from_cache",
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    data_requests.append(dr)
    _save("data_requests.json", data_requests)

    # Apply filters
    symf = symbol.strip().upper() if isinstance(symbol, str) and symbol.strip() else None
    mktf = market.strip().upper() if isinstance(market, str) and market.strip() else None

    filtered = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if asset_type is not None and a.get("asset_type") != asset_type:
            continue
        if status is not None and a.get("status") != status:
            continue
        if symf is not None and str(a.get("symbol", "")).upper() != symf:
            continue
        if mktf is not None and str(a.get("market") or "").upper() != mktf:
            continue
        filtered.append(a)

    # Sort by updated_at desc
    filtered.sort(key=lambda r: (_parse_dt(r.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    items = filtered[start:end]

    return {
        "data": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": end < total,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def upsert_asset(api_key, asset_type, symbol, asset_id=None, market=None, name=None, currency=None, status=None, metadata=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(32)
        return f"{prefix}_{ms:x}{rnd:x}".lower()

    # Validation (relaxed api_key pattern)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if asset_type not in ("equity", "forex_currency", "crypto"):
        return _err("VALIDATION_ERROR", "asset_type must be one of: equity, forex_currency, crypto.")
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    if asset_id is not None and (not isinstance(asset_id, str) or not asset_id.strip()):
        return _err("VALIDATION_ERROR", "asset_id must be a non-empty string when provided.")
    if market is not None and not isinstance(market, str):
        return _err("VALIDATION_ERROR", "market must be a string when provided.")
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string when provided.")
    if currency is not None and not isinstance(currency, str):
        return _err("VALIDATION_ERROR", "currency must be a string when provided.")
    if status is not None and status not in ("active", "inactive"):
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive.")
    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided.")

    api_keys = _load("api_keys.json")
    assets = _load("assets.json")
    data_requests = _load("data_requests.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")

    sym = symbol.strip().upper()
    mkt = market.strip() if isinstance(market, str) and market.strip() else None

    # Create one data_requests row for audit (tool_name enum does not include upsert_asset; record as get_company_overview)
    import hashlib
    fp = hashlib.sha256(json.dumps({"tool_name": "upsert_asset", "asset_id": asset_id, "asset_type": asset_type, "symbol": sym, "market": mkt}, sort_keys=True).encode("utf-8")).hexdigest()
    req_id = _new_id("req")
    dr = {
        "id": req_id,
        "api_key_id": api_key,
        "tool_name": "get_company_overview",
        "asset_id": asset_id.strip() if isinstance(asset_id, str) and asset_id.strip() else None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": None,
        "request_fingerprint": fp,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    data_requests.append(dr)
    _save("data_requests.json", data_requests)

    def _update_dr(final_status, http_status, error_code=None, error_message=None):
        dr["status"] = final_status
        dr["http_status"] = http_status
        dr["error_code"] = error_code
        dr["error_message"] = error_message
        dr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("data_requests.json", data_requests)

    # Upsert logic
    existing = None
    if asset_id:
        existing = next((a for a in assets if isinstance(a, dict) and a.get("id") == asset_id.strip()), None)
        if not existing:
            _update_dr("failed", 404, "NOT_FOUND", "Asset id not found for update.")
            return _err("NOT_FOUND", "Asset id not found for update.", asset_id=asset_id.strip())

    # Uniqueness: (asset_type, symbol, market)
    for a in assets:
        if not isinstance(a, dict):
            continue
        if existing and a.get("id") == existing.get("id"):
            continue
        if a.get("asset_type") == asset_type and str(a.get("symbol", "")).upper() == sym and (a.get("market") or None) == mkt:
            _update_dr("failed", 409, "CONFLICT", "An asset with the same (asset_type, symbol, market) already exists.")
            return _err("CONFLICT", "An asset with the same (asset_type, symbol, market) already exists.", asset_type=asset_type, symbol=sym, market=mkt)

    if existing:
        # immutable identity: asset_type, symbol, market cannot change
        if existing.get("asset_type") != asset_type or str(existing.get("symbol", "")).upper() != sym or (existing.get("market") or None) != mkt:
            _update_dr("failed", 409, "CONFLICT", "Immutable identity fields cannot be changed for an existing asset.")
            return _err("CONFLICT", "Immutable identity fields cannot be changed for an existing asset.", asset_id=existing.get("id"))

        # lifecycle transition for status if provided
        if status is not None and status != existing.get("status"):
            transitions = {"active": ["inactive"], "inactive": ["active"]}
            if status not in transitions.get(existing.get("status"), []):
                _update_dr("failed", 409, "INVALID_TRANSITION", "Invalid status transition for asset.")
                return _err("INVALID_TRANSITION", "Invalid status transition for asset.", from_status=existing.get("status"), to_status=status)

        existing["name"] = name if name is not None else existing.get("name")
        existing["currency"] = currency if currency is not None else existing.get("currency")
        if status is not None:
            existing["status"] = status
        if metadata is not None:
            existing["metadata"] = metadata
        if existing.get("metadata") is None:
            existing["metadata"] = {}
        existing["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

        for i, a in enumerate(assets):
            if isinstance(a, dict) and a.get("id") == existing.get("id"):
                assets[i] = existing
                break
        _save("assets.json", assets)
        _update_dr("succeeded", 200)
        return {"asset": existing, "created": False, "latency_ms": int((time.time() - t0) * 1000)}

    # Create new
    new_asset = {
        "id": asset_id.strip() if asset_id else _new_id("ast"),
        "asset_type": asset_type,
        "symbol": sym,
        "market": mkt,
        "name": name,
        "currency": currency,
        "status": status if status is not None else "active",
        "metadata": metadata if isinstance(metadata, dict) else {},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    assets.append(new_asset)
    _save("assets.json", assets)
    _update_dr("succeeded", 200)
    return {"asset": new_asset, "created": True, "latency_ms": int((time.time() - t0) * 1000)}

def list_data_requests(api_key, status=None, tool_name=None, asset_id=None, base_currency_asset_id=None, quote_currency_asset_id=None, created_after=None, created_before=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0032000" if __import__("os").path.isdir("./environment_mix/0032000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Validation (relaxed api_key pattern)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    allowed_status = ("queued", "fetching", "served_from_cache", "succeeded", "failed", "rate_limited")
    allowed_tool = ("get_stock_price", "get_company_overview", "get_daily_time_series", "get_weekly_time_series", "get_forex_rate", "get_crypto_price", "get_technical_indicator")
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status must be a valid data_requests status.")
    if tool_name is not None and tool_name not in allowed_tool:
        return _err("VALIDATION_ERROR", "tool_name must be a valid tool name.")
    for nm, v in (("asset_id", asset_id), ("base_currency_asset_id", base_currency_asset_id), ("quote_currency_asset_id", quote_currency_asset_id)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            return _err("VALIDATION_ERROR", f"{nm} must be a non-empty string when provided.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")

    ca = _parse_dt(created_after) if created_after is not None else None
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.")
    if ca and cb and not (ca < cb):
        return _err("VALIDATION_ERROR", "created_after must be < created_before.")

    api_keys = _load("api_keys.json")
    data_requests = _load("data_requests.json")

    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key), None)
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is invalid or not active.")

    # Log this call as a data_request (enum-safe: use get_company_overview)
    import hashlib, random
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(32)
        return f"{prefix}_{ms:x}{rnd:x}".lower()
    fp = hashlib.sha256(json.dumps({"tool_name": "list_data_requests", "filters": {"status": status, "tool_name": tool_name}}, sort_keys=True).encode("utf-8")).hexdigest()
    dr_log = {
        "id": _new_id("req"),
        "api_key_id": api_key,
        "tool_name": "get_company_overview",
        "asset_id": None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": None,
        "request_fingerprint": fp,
        "status": "succeeded",
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": now.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "updated_at": now.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
    }
    data_requests.append(dr_log)
    _save("data_requests.json", data_requests)

    rows = []
    for r in data_requests:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if asset_id is not None and r.get("asset_id") != asset_id:
            continue
        if base_currency_asset_id is not None and r.get("base_currency_asset_id") != base_currency_asset_id:
            continue
        if quote_currency_asset_id is not None and r.get("quote_currency_asset_id") != quote_currency_asset_id:
            continue
        cdt = _parse_dt(r.get("created_at"))
        if ca and (cdt is None or cdt < ca):
            continue
        if cb and (cdt is None or cdt >= cb):
            continue
        rows.append(r)

    rows.sort(key=lambda x: (_parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    return {
        "data_requests": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "latency_ms": int((time.time() - t0) * 1000),
    }

