        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _coerce_rows(blob):
        if isinstance(blob, dict) and isinstance(blob.get("rows"), list):
            return blob["rows"]
        if isinstance(blob, list):
            return blob
        return []

    def _save_rows(filename, existing_blob, rows):
        if isinstance(existing_blob, dict) and "rows" in existing_blob and isinstance(existing_blob["rows"], list):
            existing_blob["rows"] = rows
            _save(filename, existing_blob)
        else:
            _save(filename, rows)

    def _normalize_row_for_return(r):
        if not isinstance(r, dict):
            return r
        out = dict(r)
        for k in ("created_at", "updated_at", "last_used_at", "expires_at", "fetched_at", "timestamp"):
            if k in out:
                out[k] = _iso(out.get(k))
        return out

    def _fingerprint(tool_name, api_key_id, data_request_id):
        # Deterministic; used for cache/idempotency & audit parity
        s = json.dumps(
            {"tool_name": tool_name, "api_key_id": api_key_id, "data_request_id": data_request_id},
            sort_keys=True,
            separators=(",", ":"),
        )
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        # ULID-like enough for this datastore; collision-resistant per ms
        now = _utc_now()
        base = int(now.timestamp() * 1000)
        h = hashlib.sha256(f"{prefix}:{base}:{os.getpid()}".encode("utf-8")).hexdigest()[:16]
        return f"{prefix}_01{base:x}{h}".lower()

    # ---- input validation (relaxed vs pattern; accept real datastore ids) ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
    if not isinstance(data_request_id, str) or not data_request_id.strip():
        return _err("VALIDATION_ERROR", "data_request_id must be a non-empty string.", field="data_request_id")

    api_key = api_key.strip()
    data_request_id = data_request_id.strip()

    # ---- load store ----
    api_keys_blob = _load("api_keys.json")
    data_reqs_blob = _load("data_requests.json")

    api_keys = _coerce_rows(api_keys_blob)
    data_requests = _coerce_rows(data_reqs_blob)

    # ---- authenticate (by id OR client-visible value; do NOT compare to hash) ----
    # This service's tool passes api_key as an id. Some stores may also include a plaintext "key" column,
    # but schema says only key_hash exists; so we authenticate by id only.
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        # must still create a data_requests row tied to an active api_key: impossible here => UNAUTHORIZED
        return _err("UNAUTHORIZED", "Invalid API key.", api_key=api_key)

    now = _utc_now()
    today = now.date()
    minute_ago = now - datetime.timedelta(seconds=60)

    # ---- quotas (daily/minute request count) and vendor daily calls ----
    # Count ALL requests created by this key within window (including failures), per business rule.
    def _created_at_dt(r):
        return _parse_dt(r.get("created_at")) if isinstance(r, dict) else None

    daily_req_count = 0
    minute_req_count = 0
    daily_vendor_calls = 0
    for r in data_requests:
        if not isinstance(r, dict) or r.get("api_key_id") != key_row.get("id"):
            continue
        cadt = _created_at_dt(r)
        if cadt is None:
            continue
        if cadt.date() == today:
            daily_req_count += 1
            vcc = r.get("vendor_call_count")
            if isinstance(vcc, int) and vcc > 0:
                daily_vendor_calls += vcc
        if cadt >= minute_ago:
            minute_req_count += 1

    quota_daily_requests = key_row.get("quota_daily_requests")
    quota_minute_requests = key_row.get("quota_minute_requests")
    quota_daily_vendor_calls = key_row.get("quota_daily_vendor_calls")

    if not isinstance(quota_daily_requests, int) or quota_daily_requests < 0:
        return _err("VALIDATION_ERROR", "API key quota_daily_requests is invalid in datastore.", api_key_id=key_row.get("id"))
    if not isinstance(quota_minute_requests, int) or quota_minute_requests < 0:
        return _err("VALIDATION_ERROR", "API key quota_minute_requests is invalid in datastore.", api_key_id=key_row.get("id"))
    if not isinstance(quota_daily_vendor_calls, int) or quota_daily_vendor_calls < 0:
        return _err("VALIDATION_ERROR", "API key quota_daily_vendor_calls is invalid in datastore.", api_key_id=key_row.get("id"))

    # ---- create exactly one data_requests row for this tool call ----
    req_id = _new_id("req")
    fp = _fingerprint("get_data_request", key_row.get("id"), data_request_id)
    req_row = {
        "id": req_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "get_data_request",
        "asset_id": None,
        "base_currency_asset_id": None,
        "quote_currency_asset_id": None,
        "indicator": None,
        "interval": None,
        "time_period": None,
        "series_type": None,
        "outputsize": None,
        "vendor_function": None,
        "request_fingerprint": fp,
        "status": "queued",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "vendor_call_count": 0,
        "response_snapshot_id": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    data_requests.append(req_row)

    def _persist_all():
        _save_rows("data_requests.json", data_reqs_blob, data_requests)
        # update key last_used_at only on succeeded requests (below)

    # If key not active: must end in rate_limited or failed; vendor_call_count=0
    if key_row.get("status") != "active":
        req_row["status"] = "failed"
        req_row["http_status"] = 401
        req_row["error_code"] = "API_KEY_INACTIVE"
        req_row["error_message"] = "API key is not active."
        req_row["updated_at"] = _iso(_utc_now())
        _persist_all()
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=key_row.get("id"), status=key_row.get("status"))

    # Quota checks: if exceeded, request must end rate_limited, no vendor calls
    if daily_req_count + 1 > quota_daily_requests:
        req_row["status"] = "rate_limited"
        req_row["http_status"] = 429
        req_row["error_code"] = "QUOTA_DAILY_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded for this API key."
        req_row["updated_at"] = _iso(_utc_now())
        _persist_all()
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", api_key_id=key_row.get("id"))

    if minute_req_count + 1 > quota_minute_requests:
        req_row["status"] = "rate_limited"
        req_row["http_status"] = 429
        req_row["error_code"] = "QUOTA_MINUTE_EXCEEDED"
        req_row["error_message"] = "Minute request quota exceeded for this API key."
        req_row["updated_at"] = _iso(_utc_now())
        _persist_all()
        return _err("RATE_LIMIT", "Minute request quota exceeded.", api_key_id=key_row.get("id"))

    # Vendor daily call quota: this endpoint never calls vendor, so it cannot exceed vendor quota by itself.
    # Still, if already exceeded in store, this request must be blocked before upstream fetch.
    if daily_vendor_calls > quota_daily_vendor_calls:
        req_row["status"] = "rate_limited"
        req_row["http_status"] = 429
        req_row["error_code"] = "VENDOR_CALLS_DAILY_EXCEEDED"
        req_row["error_message"] = "Daily vendor call budget exceeded; request blocked before upstream fetch."
        req_row["updated_at"] = _iso(_utc_now())
        _persist_all()
        return _err("RATE_LIMIT", "Daily vendor call budget exceeded.", api_key_id=key_row.get("id"))

    # ---- fetch the requested data_requests row (authorization by api_key_id) ----
    target = None
    for r in data_requests:
        if isinstance(r, dict) and r.get("id") == data_request_id and r.get("api_key_id") == key_row.get("id"):
            target = r
            break

    # Lifecycle transitions must be valid: queued -> fetching -> succeeded/failed
    # This tool does not call vendor; treat as local "fetch"
    req_row["status"] = "fetching"
    req_row["updated_at"] = _iso(_utc_now())

    if target is None:
        req_row["status"] = "failed"
        req_row["http_status"] = 404
        req_row["error_code"] = "NOT_FOUND"
        req_row["error_message"] = "Data request not found for this API key."
        req_row["updated_at"] = _iso(_utc_now())
        _persist_all()
        return _err("NOT_FOUND", "Data request not found.", data_request_id=data_request_id)

    # succeed
    req_row["status"] = "succeeded"
    req_row["http_status"] = 200
    req_row["updated_at"] = _iso(_utc_now())

    # update api_keys.last_used_at on successful request
    key_row["last_used_at"] = _iso(_utc_now())
    key_row["updated_at"] = _iso(_utc_now())

    _save_rows("data_requests.json", data_reqs_blob, data_requests)
    _save_rows("api_keys.json", api_keys_blob, api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data_request": _normalize_row_for_return(target),
        "request": _normalize_row_for_return(req_row),
        "meta": {
            "latency_ms": latency_ms,
        },
    }
